#!/usr/bin/env python3 import sys from pathlib import Path mode,out=sys.argv[1],Path(sys.argv[2]) style='<style>.t{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;fill:#e6edf3}.p{fill:#b56cff}.s{fill:#8b949e}</style>' def make(body,title): return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 300"><title>{title}</title><rect width="1000" height="300" rx="28" fill="#0d1117"/>{style}{body}</svg>' if mode=="arcade": body='''<text x="500" y="65" text-anchor="middle" class="t p" font-size="30" font-weight="700">FARREL ARCADE</text><text x="500" y="105" text-anchor="middle" class="t s" font-size="16">DESIGN - CODE - GAME</text><rect x="160" y="125" width="680" height="100" rx="18" fill="#161b22" stroke="#30363d"/><text x="500" y="165" text-anchor="middle" class="t" font-size="20">SELECT YOUR EXPERIENCE</text><text x="500" y="200" text-anchor="middle" class="t p" font-size="18">SNAKE - TIC-TAC-TOE - ROCKBEAR</text><circle cx="205" cy="260" r="7" class="p"><animate attributeName="opacity" values=".2;1;.2" dur="1.2s" repeatCount="indefinite"/></circle><text x="225" y="266" class="t s" font-size="14">SYSTEM ONLINE</text>''' title="Farrel Arcade" elif mode=="terminal": body='''<text x="54" y="52" class="t p" font-size="22">$ farrel --boot</text><text x="54" y="92" class="t" font-size="17">&gt; loading portfolio...</text><text x="54" y="125" class="t" font-size="17">&gt; design ........ <tspan class="p">OK</tspan></text><text x="54" y="158" class="t" font-size="17">&gt; coding ........ <tspan class="p">OK</tspan></text><text x="54" y="191" class="t" font-size="17">&gt; 3D ............ <tspan class="p">OK</tspan></text><text x="54" y="224" class="t" font-size="17">&gt; game .......... <tspan class="p">BUILDING</tspan></text><text x="54" y="260" class="t p" font-size="18">&gt; system_ready_ <animate attributeName="opacity" values="1;0;1" dur="1s" repeatCount="indefinite"/></text>''' title="Terminal Boot" else: body='''<text x="500" y="48" text-anchor="middle" class="t p" font-size="26" font-weight="700">CREATIVE PIPELINE</text><text x="150" y="150" text-anchor="middle" class="t" font-size="18">DESIGN</text><text x="350" y="150" text-anchor="middle" class="t" font-size="18">FIGMA</text><text x="550" y="150" text-anchor="middle" class="t" font-size="18">3D</text><text x="750" y="150" text-anchor="middle" class="t" font-size="18">CODE</text><text x="900" y="150" text-anchor="middle" class="t" font-size="18">GAME</text><path d="M190 145H310 M390 145H510 M590 145H710 M790 145H860" stroke="#b56cff" stroke-width="3" stroke-dasharray="20 20"><animate attributeName="stroke-dashoffset" from="0" to="-40" dur="1s" repeatCount="indefinite"/></path><text x="500" y="230" text-anchor="middle" class="t s" font-size="15">IDEA - PROTOTYPE - VISUAL - EXPERIENCE</text>''' title="Creative Pipeline" out.parent.mkdir(parents=True,exist_ok=True) out.write_text(make(body,title))
